use nom::{IResult, bytes::complete::take};

#[derive(Debug)]
struct EthernetHeader {
    dest_mac: [u8; 6],
    src_mac: [u8; 6],
    ethertype: [u8; 2],
}

fn parse_ethernet(input: &[u8]) -> IResult<&[u8], EthernetHeader> {
    let (input, dest_mac) = take(6usize)(input)?;
    let (input, src_mac) = take(6usize)(input)?;
    let (input, ethertype) = take(2usize)(input)?;

    Ok((input, EthernetHeader {
        dest_mac: dest_mac.try_into().unwrap(),
        src_mac: src_mac.try_into().unwrap(),
        ethertype: ethertype.try_into().unwrap(),
    }))
}

fn get_payload_length(header_bytes: &[u8]) -> u16 {
    // Extract 2 bytes and convert from Big Endian (network order)
    let length_bytes: [u8; 2] = header_bytes[0..2].try_into().expect("Slice to array failed");
    let length = u16::from_be_bytes(length_bytes);

    println!("Parsed payload length: {}", length);
    length
}

let raw_data = [0x05, 0xDC]; // 1500 in hex
get_payload_length(&raw_data);

