use aya_bpf::{macros::kprobe, programs::ProbeContext};
use aya_log_ebpf::info;

#[kprobe(name="trace_exec")]
pub fn trace_exec(ctx: ProbeContext) -> u32 {
    match try_trace_exec(ctx) {
        Ok(ret) => ret,
        Err(_) => 1,
    }
}

fn try_trace_exec(ctx: ProbeContext) -> Result<u32, u32> {
    info!(&ctx, "[!] Process execution detected!");
    Ok(0)
}

use aya_bpf::helpers::gen::bpf_get_current_comm;

fn get_name() -> [u8; 16] {
    let mut comm = [0u8; 16];
    // bpf_get_current_comm fills the buffer with the process name
    unsafe {
        bpf_get_current_comm(&mut comm as *mut _ as *mut core::ffi::c_void, 16);
    }
    comm
}

