use yara::Compiler;

fn scan_buffer(data: &[u8], rule_str: &str) {
    let compiler = Compiler::new().unwrap();
    let compiler = compiler.add_rules_str(rule_str).expect("Failed to parse rule");
    let rules = compiler.compile_rules().expect("Failed to compile");

    let results = rules.scan_mem(data, 10).expect("Scan failed");
    for matched_rule in results {
        println!("[!] Match found: {}", matched_rule.identifier);
    }
}

use tokio::sync::mpsc;

struct EdrEvent { pid: u32, comm: String }

async fn run_agent(mut rx: mpsc::Receiver<EdrEvent>) {
    while let Some(event) = rx.recv().await {
        println!("[*] Analyzing new process: {} (PID: {})", event.comm, event.pid);

        // Perform YARA scan in a separate thread to avoid blocking the loop
        tokio::spawn(async move {
            if perform_scan(&event.comm) {
                trigger_alert(event);
            }
        });
    }
}

use reqwest::Client;

async fn trigger_alert(event: EdrEvent) -> Result<(), reqwest::Error> {
    let client = Client::new();
    let payload = serde_json::json!({
        "alert_type": "malicious_process",
        "pid": event.pid,
        "name": event.comm
    });

    client.post("https://siem.local/alerts")
        .json(&payload)
        .send()
        .await?;

    Ok(())
}
